/**
 * Any message in a conversation. Discriminated by role.
 */
export const Message = Schema.Union(
  [DeveloperMessage, SystemMessage, AssistantMessage, UserMessage, ToolMessage, ActivityMessage, ReasoningMessage],
  { mode: "oneOf" },
).annotate({ description: "Any message in a conversation. Discriminated by role.", identifier: "Message" });
export type Message =
  | DeveloperMessage
  | SystemMessage
  | AssistantMessage
  | UserMessage
  | ToolMessage
  | ActivityMessage
  | ReasoningMessage;

/**
 * The complete set of messages the producer owns, in order. Conversation-wide rather than a plain overwrite: a consumer may keep messages of its own that no producer tracks, so exactly how a snapshot reconciles with those is behavioural and belongs in the prose. Being conversation-wide it cannot belong to a single subagent, so it carries no attribution; it does establish which subagent owns each message it contains, through the messages themselves.
 */
export const MessagesSnapshotEvent = Schema.Struct({
  type: Schema.Literal("MESSAGES_SNAPSHOT").annotate({
    description: "Which event this is. Each event definition narrows this to a single value.",
  }),
  timestamp: Schema.optionalKey(
    Schema.Finite.annotate({
      description:
        "When the event was created. Bounded to the range JSON numbers survive a round trip in, so the value a consumer reads is the value the producer wrote. Deliberately not a float. The unit is not constrained here, because it never has been stated normatively; every SDK that sets it in practice uses milliseconds since the Unix epoch, and a producer choosing another unit will be misread by consumers even though it validates. Nothing in the protocol computes with this value.",
    })
      .check(Schema.isInt().annotate({ expected: "an integer" }))
      .check(
        Schema.isGreaterThanOrEqualTo(-9007199254740991).annotate({
          expected: "a value greater than or equal to -9007199254740991",
        }),
      )
      .check(
        Schema.isLessThanOrEqualTo(9007199254740991).annotate({
          expected: "a value less than or equal to 9007199254740991",
        }),
      ),
  ),
  rawEvent: Schema.optionalKey(
    Schema.Json.annotate({
      expected: "JSON value",
      description:
        "The provider-native event this one was translated from, carried verbatim for debugging and for consumers that need detail the protocol does not model. Any JSON value.",
    }),
  ),
  metadata: Schema.optionalKey(
    Schema.suspend((): Schema.Codec<Metadata> => Metadata).annotate({
      description: "Extra information attached to this event.",
    }),
  ),
  messages: Schema.Array(Message).annotate({ description: "The messages the producer is declaring, in order." }),
}).annotate({
  description:
    "The complete set of messages the producer owns, in order. Conversation-wide rather than a plain overwrite: a consumer may keep messages of its own that no producer tracks, so exactly how a snapshot reconciles with those is behavioural and belongs in the prose. Being conversation-wide it cannot belong to a single subagent, so it carries no attribution; it does establish which subagent owns each message it contains, through the messages themselves.",
  identifier: "MessagesSnapshotEvent",
});
export type MessagesSnapshotEvent = {
  readonly type: "MESSAGES_SNAPSHOT";
  readonly timestamp?: number;
  readonly rawEvent?: Schema.Json;
  readonly metadata?: Metadata;
  readonly messages: ReadonlyArray<Message>;
};

/**
 * A request to run an agent. Also echoed back as RUN_STARTED.input. Only threadId, runId and messages are required: those are the three the SDKs already agree on, and for tools and context an absent key and an empty array mean the same thing, so requiring them would catch nothing a producer could get wrong.
 */
export const RunAgentInput = Schema.Struct({
  threadId: Schema.String.annotate({ description: "The conversation this run belongs to." }),
  runId: Schema.String.annotate({ description: "Identifies this run." }),
  protocolVersion: Schema.optionalKey(
    Schema.String.annotate({
      description:
        'The protocol version this consumer speaks, such as "1.0". Absent means the input was produced before the protocol carried a version — the versioning rules in the prose govern what each side does with that. Sent in-band rather than by the transport, so a recorded exchange stays self-describing.',
    }),
  ),
  parentRunId: Schema.optionalKey(Schema.String.annotate({ description: "The run that spawned this one." })),
  state: Schema.optionalKey(
    Schema.suspend((): Schema.Codec<State> => State).annotate({ description: "The state the run starts from." }),
  ),
  messages: Schema.Array(Message).annotate({ description: "The conversation so far, in order." }),
  tools: Schema.optionalKey(
    Schema.Array(Tool).annotate({ description: "The tools the agent may call. Absent means none." }),
  ),
  context: Schema.optionalKey(
    Schema.Array(Context).annotate({ description: "Ambient information for the run. Absent means none." }),
  ),
  forwardedProps: Schema.optionalKey(
    Schema.Json.annotate({
      expected: "JSON value",
      description: "Application-specific values passed through to the agent untouched. Any JSON value.",
    }),
  ),
  resume: Schema.optionalKey(
    Schema.Array(ResumeEntry).annotate({
      description: "Answers to the interrupts that ended a previous run, when this run continues from one.",
    }),
  ),
}).annotate({
  description:
    "A request to run an agent. Also echoed back as RUN_STARTED.input. Only threadId, runId and messages are required: those are the three the SDKs already agree on, and for tools and context an absent key and an empty array mean the same thing, so requiring them would catch nothing a producer could get wrong.",
  identifier: "RunAgentInput",
});
export type RunAgentInput = {
  readonly threadId: string;
  readonly runId: string;
  readonly protocolVersion?: string;
  readonly parentRunId?: string;
  readonly state?: State;
  readonly messages: ReadonlyArray<Message>;
  readonly tools?: ReadonlyArray<Tool>;
  readonly context?: ReadonlyArray<Context>;
  readonly forwardedProps?: Schema.Json;
  readonly resume?: ReadonlyArray<ResumeEntry>;
};

